#!/usr/bin/env python3
# test_compare.py - tests for packages/video-export-qa/scripts/qa_compare.py (stdlib unittest, real ffmpeg).
#
# Purpose: prove qa_compare.py finds the exact first differing frame, reports count and resolution
#          differences, measures PSNR correctly, and that each check can actually fail.
# Inputs:  none. Clips are generated by ffmpeg from a test pattern under
#          _work/video-export-qa/gif-compare/compare/. Lossless codecs (FFV1, x264 -qp 0) are used
#          where exactness matters, so the only differences are the ones the test introduces.
# Outputs: unittest results and the generated clips in the _work folder.
# Run:     python -B -m unittest discover -s tests/video-export-qa -p "test_compare.py"
#
# PSNR is cross-checked by decoding both files to raw yuv420p in Python and computing the
# per-frame value from the squared error over all Y, U and V samples.

import ast
import hashlib
import json
import math
import os
import shutil
import subprocess
import sys
import unittest

from ffmpeg_fixtures import fixture_command, supports_option, private_work_folder

sys.dont_write_bytecode = True  # keep __pycache__ out of the package and the tests

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.abspath(os.path.join(HERE, "..", ".."))
SCRIPTS = os.path.join(ROOT, "packages", "video-export-qa", "scripts")
CMP_SCRIPT = os.path.join(SCRIPTS, "qa_compare.py")
WORK = private_work_folder(ROOT, "gif-compare", "compare")
sys.path.insert(0, SCRIPTS)

import common  # noqa: E402
import qa_compare  # noqa: E402

FFMPEG = shutil.which("ffmpeg")
FFPROBE = shutil.which("ffprobe")
V = {}  # clip name -> path, filled by setUpModule

W, H = 160, 90
FRAMES = 24
FFV1 = ["-c:v", "ffv1", "-level", "3"]
X264_LOSSLESS_LONG_GOP = ["-c:v", "libx264", "-qp", "0", "-g", "250", "-bf", "3"]
X264_LOSSY = ["-c:v", "libx264", "-crf", "18"]


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def run_cmd(cmd):
    proc = subprocess.run(fixture_command(cmd), capture_output=True)
    if proc.returncode != 0:
        raise AssertionError("command failed: %s\n%s" % (cmd, proc.stderr.decode("utf-8", "replace")))
    return proc.stdout


def make_clip(name, codec, frames=FRAMES, size="%dx%d" % (W, H), alter=(), pix_fmt="yuv420p", slow=False,
              audio=False, shared_timestamps=False):
    """Generate a clip from the test pattern; frames listed in alter get a red box (and nothing else changes).

    shared_timestamps=True gives frames 2k and 2k+1 the same timestamp (a trap for ffmpeg's default frame sync).
    """
    path = os.path.join(WORK, name)
    boxes = [("drawbox=x=10:y=10:w=60:h=40:color=red:t=fill:enable=eq(n\\,%d)" % n) for n in alter]
    chain = boxes or ["drawbox=x=10:y=10:w=60:h=40:color=red:t=fill:enable=eq(n\\,-1)"]   # never enabled
    vf = ",".join(chain) + ",format=%s" % pix_fmt + (",setpts=PTS*2" if slow else "")
    if shared_timestamps:
        vf += ",setpts=floor(N/2)/24/TB"
    cmd = [FFMPEG, "-hide_banner", "-nostdin", "-v", "error", "-y", "-f", "lavfi",
           "-i", "testsrc2=size=%s:rate=24" % size]
    if audio:
        cmd += ["-f", "lavfi", "-i", "sine=frequency=440:duration=1"]
    cmd += ["-vf", vf, "-frames:v", str(frames)]
    if shared_timestamps:
        cmd += ["-fps_mode", "passthrough"]   # keep the shared timestamps instead of letting ffmpeg fix them
    if audio:
        cmd += ["-c:a", "pcm_s16le", "-shortest"]
    run_cmd(cmd + codec + [path])
    return path


def file_sha(path):
    with open(path, "rb") as fh:
        return hashlib.sha256(fh.read()).hexdigest()


def raw_yuv420p_frames(path):
    """Decoded frames as raw yuv420p byte strings (independent of qa_compare)."""
    data = run_cmd([FFMPEG, "-hide_banner", "-nostdin", "-v", "error", "-i", path, "-map", "0:v:0",
                    "-fps_mode", "passthrough", "-f", "rawvideo", "-pix_fmt", "yuv420p", "-"])
    size = W * H * 3 // 2
    assert len(data) % size == 0, "unexpected raw size"
    return [data[i:i + size] for i in range(0, len(data), size)]


def independent_psnr(path_a, path_b):
    """Per-frame PSNR in dB from the squared error over every Y, U and V sample (inf when identical)."""
    values = []
    for fa, fb in zip(raw_yuv420p_frames(path_a), raw_yuv420p_frames(path_b)):
        sq = sum((x - y) * (x - y) for x, y in zip(fa, fb))
        values.append(float("inf") if sq == 0 else 10.0 * math.log10(255.0 * 255.0 * len(fa) / sq))
    return values


def check_of(doc, check_id):
    return next(c for c in doc["checks"] if c["id"] == check_id)


def statuses(doc):
    return {c["id"]: c["status"] for c in doc["checks"]}


def cli(*args):
    proc = subprocess.run([sys.executable, "-I", "-B", CMP_SCRIPT] + list(args), capture_output=True)
    return proc.returncode, proc.stdout.decode("utf-8", "replace"), proc.stderr.decode("utf-8", "replace")


def compare(a, b, *extra):
    """Run the CLI with --json and return (exit code, parsed JSON or None, stderr)."""
    code, out, err = cli(a, b, "--json", *extra)
    return code, (json.loads(out) if out.strip().startswith("{") else None), err


def setUpModule():
    if not FFMPEG or not FFPROBE:
        raise unittest.SkipTest("ffmpeg and ffprobe are required on PATH")
    os.makedirs(WORK, exist_ok=True)
    V["a"] = make_clip("a.mkv", FFV1)                                          # reference, lossless
    V["copy"] = os.path.join(WORK, "a_copy.mkv")
    shutil.copyfile(V["a"], V["copy"])                                         # byte-identical copy
    V["remux"] = os.path.join(WORK, "a_remux.mkv")                             # same frames, different file bytes
    run_cmd([FFMPEG, "-hide_banner", "-nostdin", "-v", "error", "-y", "-i", V["a"], "-c", "copy", V["remux"]])
    V["alt7"] = make_clip("alt7.mkv", FFV1, alter=(7,))
    V["alt7_20"] = make_clip("alt7_20.mkv", FFV1, alter=(7, 20))
    V["alt0"] = make_clip("alt0.mkv", FFV1, alter=(0,))
    V["alt23"] = make_clip("alt23.mkv", FFV1, alter=(23,))
    V["short23"] = make_clip("short23.mkv", FFV1, frames=23)                   # A with its last frame missing
    V["long25"] = make_clip("long25.mkv", FFV1, frames=25)                     # A with one extra frame
    V["alt7_short23"] = make_clip("alt7_short23.mkv", FFV1, frames=23, alter=(7,))
    V["big"] = make_clip("big.mkv", FFV1, size="320x180")                      # different resolution
    V["yuv444"] = make_clip("yuv444.mkv", FFV1, pix_fmt="yuv444p")             # same picture, other pixel format
    V["slow"] = make_clip("slow.mkv", FFV1, slow=True)                         # same frames, twice the spacing
    V["slow_alt7"] = make_clip("slow_alt7.mkv", FFV1, slow=True, alter=(7,))
    V["audio"] = make_clip("with_audio.mkv", FFV1, audio=True)                 # same video plus an audio track
    V["dup"] = make_clip("dup_timestamps.mkv", FFV1, frames=12, shared_timestamps=True)
    V["dup_copy"] = os.path.join(WORK, "dup_timestamps_copy.mkv")
    shutil.copyfile(V["dup"], V["dup_copy"])
    V["dup_alt9"] = make_clip("dup_timestamps_alt9.mkv", FFV1, frames=12, alter=(9,), shared_timestamps=True)
    V["h264"] = make_clip("a_h264.mp4", X264_LOSSLESS_LONG_GOP)                # lossless H.264, one long GOP
    V["h264_alt20"] = make_clip("alt20_h264.mp4", X264_LOSSLESS_LONG_GOP, alter=(20,))
    V["lossy"] = make_clip("a_lossy.mp4", X264_LOSSY)
    V["lossy_alt7"] = make_clip("alt7_lossy.mp4", X264_LOSSY, alter=(7,))
    V["wav"] = os.path.join(WORK, "tone.wav")
    run_cmd([FFMPEG, "-hide_banner", "-nostdin", "-v", "error", "-y", "-f", "lavfi", "-i",
             "sine=frequency=440:duration=0.2", V["wav"]])
    V["text"] = os.path.join(WORK, "not_video.txt")
    with open(V["text"], "w") as fh:
        fh.write("this is not a video\n")


# ---------------------------------------------------------------------------
# Pure functions
# ---------------------------------------------------------------------------

FRAMEMD5_SAMPLE = """#format: frame checksums
#version: 2
#hash: MD5
#software: Lavf62.12.101
#tb 0: 1/24
#media_type 0: video
#codec_id 0: rawvideo
#dimensions 0: 160x90
#sar 0: 1/1
#stream#, dts,        pts, duration,     size, hash
0,          0,          0,        1,    21600, bcf4850ac2f22afe9a7d083d7bfcaaee
0,          1,          1,        1,    21600, 9b72df7418003cfc2e1a129821766877
"""


class PureFunctions(unittest.TestCase):
    def test_framemd5_parse(self):
        parsed = qa_compare.parse_framemd5(FRAMEMD5_SAMPLE, "A")
        self.assertEqual((parsed["width"], parsed["height"]), (160, 90))
        self.assertEqual(parsed["hashes"], ["bcf4850ac2f22afe9a7d083d7bfcaaee", "9b72df7418003cfc2e1a129821766877"])
        self.assertEqual(parsed["pts"], [0, 1])
        self.assertEqual(parsed["sizes"], [21600, 21600])
        self.assertEqual(str(parsed["timebase"]), "1/24")

    def test_framemd5_parse_rejects_garbage(self):
        for bad in ("0, 0, 0, 1, 21600, nothex",           # hash is not 32 hex digits
                    "0, 0, 0, 1, 21600",                    # a field is missing
                    "0, 0, x, 1, 21600, " + "a" * 32,       # pts is not a number
                    "0, 0, 0, 1, big, " + "a" * 32):        # size is not a number
            with self.assertRaises(common.QAError, msg=bad):
                qa_compare.parse_framemd5(bad, "A")
        # negative control: the same line with valid fields parses
        ok = qa_compare.parse_framemd5("0, 0, 0, 1, 21600, " + "a" * 32, "A")
        self.assertEqual(ok["hashes"], ["a" * 32])
        # header-only output parses to zero frames (no exception, no frames)
        self.assertEqual(qa_compare.parse_framemd5("#format: frame checksums\n", "A")["hashes"], [])

    def test_compare_hashes(self):
        self.assertEqual(qa_compare.compare_hashes(["a", "b", "c"], ["a", "b", "c"]), ([], None))
        self.assertEqual(qa_compare.compare_hashes(["a", "b", "c"], ["a", "x", "c"]), ([1], 1))
        self.assertEqual(qa_compare.compare_hashes(["a", "b", "c"], ["x", "b", "y"]), ([0, 2], 0))
        self.assertEqual(qa_compare.compare_hashes(["a", "b", "c"], ["a", "b"]), ([], 2))   # B ends early
        self.assertEqual(qa_compare.compare_hashes(["a", "b"], ["a", "b", "c"]), ([], 2))   # A ends early
        self.assertEqual(qa_compare.compare_hashes(["a", "b", "c"], ["a", "x"]), ([1], 1))

    def test_an_empty_measurement_is_never_a_pass(self):
        empty = {"hashes": [], "pts": [], "sizes": [], "width": W, "height": H, "timebase": None}
        full = {"hashes": ["a" * 32], "pts": [0], "sizes": [1], "width": W, "height": H, "timebase": None}
        for a, b in ((empty, empty), (empty, full), (full, empty)):
            report = common.Report("qa_compare.py")
            qa_compare._check_frame_count(report, a, b)
            qa_compare._check_identical(report, a, b)
            states = {c["id"]: c["status"] for c in report.checks}
            self.assertEqual(states["frame_count_equal"], common.FAIL)
            self.assertEqual(states["identical"], common.SKIP)
            self.assertNotIn(common.PASS, states.values())
        # negative control: one real frame on each side does pass
        report = common.Report("qa_compare.py")
        qa_compare._check_frame_count(report, full, full)
        qa_compare._check_identical(report, full, full)
        self.assertEqual([c["status"] for c in report.checks], [common.PASS, common.PASS])


# ---------------------------------------------------------------------------
# Exact comparison
# ---------------------------------------------------------------------------

class ExactComparison(unittest.TestCase):
    def test_byte_identical_copy_passes(self):
        code, doc, err = compare(V["a"], V["copy"])
        self.assertEqual(code, 0, err)
        self.assertEqual(doc["overall"], "PASS")
        self.assertEqual(statuses(doc), {"frame_count_equal": "PASS", "identical": "PASS"})
        self.assertEqual(doc["info"]["a"]["frames_decoded"], FRAMES)
        self.assertEqual(doc["info"]["first_differing_frame"], None)
        self.assertEqual(doc["info"]["differing_frames"], 0)

    def test_same_pictures_in_a_different_file_still_pass(self):
        # the remuxed file has different bytes, so equality comes from decoded frames and not file hashes
        self.assertNotEqual(file_sha(V["a"]), file_sha(V["remux"]))
        code, doc, err = compare(V["a"], V["remux"])
        self.assertEqual(code, 0, err)
        self.assertEqual(check_of(doc, "identical")["status"], "PASS")
        self.assertNotEqual(doc["info"]["a"]["sha256"], doc["info"]["b"]["sha256"])

    def test_one_altered_frame_fails_with_the_right_index(self):
        for name, index in (("alt7", 7), ("alt0", 0), ("alt23", 23)):
            code, doc, err = compare(V["a"], V[name])
            self.assertEqual(code, 1, name)
            check = check_of(doc, "identical")
            self.assertEqual(check["status"], "FAIL", name)
            self.assertEqual(check["actual"]["first_differing_frame"], index, name)
            self.assertEqual(check["actual"]["differing_frames"], 1, name)
            self.assertIn("frame index %d" % index, check["detail"])
            self.assertEqual(check_of(doc, "frame_count_equal")["status"], "PASS", name)
            self.assertEqual(doc["info"]["first_differing_frame"], index)

    def test_two_altered_frames_report_the_first_and_the_count(self):
        code, doc, err = compare(V["a"], V["alt7_20"])
        self.assertEqual(code, 1)
        check = check_of(doc, "identical")
        self.assertEqual(check["actual"], {"first_differing_frame": 7, "differing_frames": 2})
        self.assertIn("2 of the 24", check["detail"])

    def test_the_order_of_the_arguments_does_not_change_the_finding(self):
        code, doc, err = compare(V["alt7"], V["a"])
        self.assertEqual(check_of(doc, "identical")["actual"]["first_differing_frame"], 7)

    def test_long_gop_h264_is_compared_frame_exactly(self):
        # lossless H.264 with one 250-frame GOP and B-frames: frame 20 is far from any keyframe
        code, doc, err = compare(V["h264"], V["h264_alt20"])
        self.assertEqual(code, 1, err)
        self.assertEqual(check_of(doc, "identical")["actual"]["first_differing_frame"], 20)
        self.assertEqual(check_of(doc, "identical")["actual"]["differing_frames"], 1)
        # negative control and cross-codec proof: lossless H.264 and FFV1 decode to the same pictures
        code, doc, err = compare(V["a"], V["h264"])
        self.assertEqual(code, 0, doc and check_of(doc, "identical"))
        self.assertEqual(doc["overall"], "PASS")

    def test_frames_sharing_a_timestamp_are_all_compared(self):
        # ffmpeg's default frame sync would drop frames that share a timestamp; this file shows the trap
        out = run_cmd([FFMPEG, "-hide_banner", "-nostdin", "-v", "error", "-i", V["dup"], "-map", "0:v:0",
                       "-f", "framemd5", "-"]).decode("utf-8")
        default_mode_frames = len([line for line in out.splitlines() if line and not line.startswith("#")])
        self.assertLess(default_mode_frames, 12)
        code, doc, err = compare(V["dup"], V["dup_alt9"])
        self.assertEqual(code, 1, err)
        self.assertEqual((doc["info"]["a"]["frames_decoded"], doc["info"]["b"]["frames_decoded"]), (12, 12))
        self.assertEqual(check_of(doc, "identical")["actual"]["first_differing_frame"], 9)
        # negative control: an identical copy of the same awkward file passes with all 12 frames counted
        code, doc, err = compare(V["dup"], V["dup_copy"])
        self.assertEqual(code, 0, err)
        self.assertEqual(doc["info"]["a"]["frames_decoded"], 12)

    def test_audio_is_not_compared(self):
        code, doc, err = compare(V["a"], V["audio"])
        self.assertEqual(code, 0, err)
        self.assertEqual(check_of(doc, "identical")["status"], "PASS")

    def test_same_picture_in_another_pixel_format_is_not_identical(self):
        code, doc, err = compare(V["a"], V["yuv444"])
        self.assertEqual(code, 1)
        self.assertEqual(check_of(doc, "identical")["status"], "FAIL")
        self.assertEqual(check_of(doc, "frame_count_equal")["status"], "PASS")
        sizes = (doc["info"]["a"]["decoded_frame_bytes"], doc["info"]["b"]["decoded_frame_bytes"])
        self.assertNotEqual(sizes[0], sizes[1])   # the decoded formats really differ
        # negative control: same pixel format and same picture passes
        self.assertEqual(compare(V["a"], V["copy"])[0], 0)

    def test_same_frames_with_different_timestamps_pass_but_say_so(self):
        code, doc, err = compare(V["a"], V["slow"])
        self.assertEqual(code, 0, err)
        check = check_of(doc, "identical")
        self.assertEqual(check["status"], "PASS")
        self.assertIs(doc["info"]["timestamps_equal"], False)
        self.assertIn("timestamps differ", check["detail"])
        # negative control: an identical copy has equal timestamps and no such note
        code, doc, err = compare(V["a"], V["copy"])
        self.assertIs(doc["info"]["timestamps_equal"], True)
        self.assertNotIn("timestamps", check_of(doc, "identical")["detail"])


class FrameCountsAndResolution(unittest.TestCase):
    def test_a_missing_last_frame_fails_both_checks(self):
        code, doc, err = compare(V["a"], V["short23"], "--min-psnr", "30")
        self.assertEqual(code, 1)
        count = check_of(doc, "frame_count_equal")
        self.assertEqual((count["status"], count["expected"], count["actual"]), ("FAIL", 24, 23))
        identical = check_of(doc, "identical")
        self.assertEqual(identical["status"], "FAIL")
        self.assertEqual(identical["actual"]["first_differing_frame"], 23)
        self.assertIn("A has 1 extra", identical["detail"])
        psnr = check_of(doc, "psnr")
        self.assertEqual(psnr["status"], "SKIP")
        self.assertIn("frame counts differ", psnr["detail"])

    def test_an_extra_frame_fails(self):
        code, doc, err = compare(V["a"], V["long25"])
        self.assertEqual(code, 1)
        self.assertEqual(check_of(doc, "frame_count_equal")["actual"], 25)
        identical = check_of(doc, "identical")
        self.assertEqual(identical["actual"]["first_differing_frame"], 24)
        self.assertIn("B has 1 extra", identical["detail"])

    def test_content_and_count_differences_name_the_content_difference_first(self):
        code, doc, err = compare(V["a"], V["alt7_short23"])
        identical = check_of(doc, "identical")
        self.assertEqual(identical["actual"]["first_differing_frame"], 7)
        self.assertIn("frame counts also differ", identical["detail"])
        self.assertEqual(identical["actual"]["differing_frames"], 2)    # frame 7 plus the missing frame 23

    def test_different_resolutions_fail_identical_and_skip_psnr(self):
        code, doc, err = compare(V["a"], V["big"], "--min-psnr", "30")
        self.assertEqual(code, 1)
        identical = check_of(doc, "identical")
        self.assertEqual(identical["status"], "FAIL")
        self.assertIn("resolution differs", identical["detail"])
        self.assertIn("160x90", identical["detail"])
        self.assertIn("320x180", identical["detail"])
        self.assertEqual(check_of(doc, "frame_count_equal")["status"], "PASS")
        psnr = check_of(doc, "psnr")
        self.assertEqual(psnr["status"], "SKIP")
        self.assertIn("resolutions differ", psnr["detail"])
        self.assertEqual((doc["info"]["a"]["width"], doc["info"]["b"]["width"]), (160, 320))

    def test_psnr_is_not_run_without_the_option(self):
        code, doc, err = compare(V["a"], V["alt7"])
        self.assertNotIn("psnr", statuses(doc))
        self.assertIsNone(doc["info"]["psnr"])


# ---------------------------------------------------------------------------
# PSNR
# ---------------------------------------------------------------------------

class Psnr(unittest.TestCase):
    def test_identical_clips_have_infinite_psnr_and_pass_any_threshold(self):
        code, doc, err = compare(V["a"], V["copy"], "--min-psnr", "100")
        self.assertEqual(code, 0, err)
        check = check_of(doc, "psnr")
        self.assertEqual((check["status"], check["actual"]), ("PASS", "inf"))
        self.assertEqual(doc["info"]["psnr"]["min_db"], "inf")
        self.assertEqual(doc["info"]["psnr"]["frames_measured"], FRAMES)
        json.dumps(doc, allow_nan=False)   # strict JSON: no Infinity / NaN tokens

    def test_altered_frame_psnr_matches_an_independent_calculation(self):
        expected = independent_psnr(V["a"], V["alt7"])
        self.assertEqual([i for i, v in enumerate(expected) if math.isfinite(v)], [7])
        worst = expected[7]
        for threshold, status, code in ((worst - 1.0, "PASS", 0), (worst + 1.0, "FAIL", 1)):
            exit_code, doc, err = compare(V["a"], V["alt7"], "--min-psnr", "%.3f" % threshold)
            # exact comparison also fails (the clips differ), so the overall exit is 1 either way
            self.assertEqual(exit_code, 1)
            psnr = check_of(doc, "psnr")
            self.assertEqual(psnr["status"], status)
            self.assertAlmostEqual(psnr["actual"], worst, delta=0.011)
            self.assertEqual(doc["info"]["psnr"]["worst_frame_index"], 7)
            self.assertEqual(doc["info"]["psnr"]["frames_below_threshold"], 0 if status == "PASS" else 1)
            self.assertIn("frame index 7", psnr["detail"])

    def test_lossy_encode_psnr_matches_an_independent_calculation(self):
        expected = independent_psnr(V["a"], V["lossy"])
        lowest = min(expected)
        code, doc, err = compare(V["a"], V["lossy"], "--min-psnr", "%.3f" % (lowest - 0.5))
        psnr = check_of(doc, "psnr")
        self.assertEqual(psnr["status"], "PASS")
        self.assertAlmostEqual(psnr["actual"], lowest, delta=0.011)
        self.assertEqual(doc["info"]["psnr"]["worst_frame_index"], expected.index(lowest))
        self.assertEqual(doc["info"]["psnr"]["frames_measured"], FRAMES)
        # a lossy encode is not bit-identical, so the exact check fails while the psnr check passes
        self.assertEqual(check_of(doc, "identical")["status"], "FAIL")
        # negative control: a threshold above the lowest PSNR fails and counts the frames below it
        code, doc, err = compare(V["a"], V["lossy"], "--min-psnr", "%.3f" % (lowest + 0.5))
        self.assertEqual(check_of(doc, "psnr")["status"], "FAIL")
        self.assertGreaterEqual(doc["info"]["psnr"]["frames_below_threshold"], 1)

    def test_psnr_pairs_frames_by_index_even_when_the_timing_differs(self):
        # A and the slowed copy hold the same pictures at different timestamps: still infinite PSNR
        code, doc, err = compare(V["a"], V["slow"], "--min-psnr", "100")
        self.assertEqual(code, 0, err)
        self.assertEqual(check_of(doc, "psnr")["actual"], "inf")
        # and an altered frame is still found at its index when the timing differs
        code, doc, err = compare(V["a"], V["slow_alt7"], "--min-psnr", "100")
        self.assertEqual(doc["info"]["psnr"]["worst_frame_index"], 7)
        self.assertEqual(doc["info"]["psnr"]["frames_below_threshold"], 1)
        self.assertEqual(check_of(doc, "psnr")["status"], "FAIL")

    def test_bad_thresholds_are_usage_errors(self):
        for value in ("0", "-5", "nan", "inf", "abc"):
            code, out, err = cli(V["a"], V["copy"], "--min-psnr", value)
            self.assertEqual(code, 2, value)


