# Command line behaviour, provenance, method
# ---------------------------------------------------------------------------

class CommandLine(unittest.TestCase):
    def test_exit_codes_0_1_2(self):
        self.assertEqual(cli(V["a"], V["copy"])[0], 0)
        code, out, err = cli(V["a"], V["alt7"])
        self.assertEqual(code, 1)
        self.assertIn("[FAIL] identical", out)
        code, out, err = cli(V["a"], os.path.join(WORK, "missing.mkv"))
        self.assertEqual(code, 2)
        self.assertIn("error:", err)
        self.assertEqual(out.strip(), "")

    def test_same_file_twice_is_refused(self):
        code, out, err = cli(V["a"], V["a"])
        self.assertEqual(code, 2)
        self.assertIn("same file", err)

    def test_files_ffmpeg_cannot_read_as_video_exit_2(self):
        for label, bad in (("audio only", V["wav"]), ("text", V["text"])):
            code, out, err = cli(V["a"], bad)
            self.assertEqual(code, 2, label)
            self.assertIn("could not decode", err)
            self.assertNotIn("PASS", out)
            code, out, err = cli(bad, V["a"])
            self.assertEqual(code, 2, label)

    def test_a_missing_ffmpeg_exits_2(self):
        code, out, err = cli(V["a"], V["copy"], "--ffmpeg", os.path.join(WORK, "no-such-ffmpeg"))
        self.assertEqual(code, 2)
        self.assertIn("not found", err)

    def test_table_output_names_both_files_and_every_check(self):
        code, out, err = cli(V["a"], V["alt7"], "--min-psnr", "30")
        self.assertIn("A: " + V["a"], out)
        self.assertIn("B: " + V["alt7"], out)
        for check_id in ("frame_count_equal", "identical", "psnr"):
            self.assertIn(check_id, out)

    def test_json_schema_and_provenance(self):
        code, doc, err = compare(V["a"], V["alt7"], "--min-psnr", "30")
        self.assertEqual(set(doc), {"tool", "file", "overall", "checks", "info", "provenance"})
        self.assertEqual(doc["tool"], "qa_compare.py")
        self.assertEqual(doc["file"], V["a"])
        self.assertEqual(doc["overall"], "FAIL")
        for c in doc["checks"]:
            self.assertEqual(set(c), {"id", "status", "expected", "actual", "detail"})
        prov = doc["provenance"]
        self.assertEqual(prov["script"], "qa_compare.py")
        self.assertEqual(prov["input"]["sha256"], file_sha(V["a"]))
        self.assertEqual(prov["input"]["size_bytes"], os.path.getsize(V["a"]))
        self.assertEqual(doc["info"]["a"]["sha256"], file_sha(V["a"]))
        self.assertEqual(doc["info"]["b"]["sha256"], file_sha(V["alt7"]))
        self.assertTrue(prov["ffmpeg_version"].startswith("ffmpeg version"))
        self.assertIsNone(prov["ffprobe_version"])     # ffprobe is not used by this script
        self.assertIsNone(prov["spec_sha256"])
        # negative control: another pair records other hashes
        other = compare(V["copy"], V["alt0"])[1]
        self.assertEqual(other["provenance"]["input"]["sha256"], file_sha(V["copy"]))
        self.assertNotEqual(other["info"]["b"]["sha256"], doc["info"]["b"]["sha256"])

    def test_decoding_is_sequential_and_never_seeks_or_drops_frames(self):
        code, doc, err = compare(V["a"], V["alt7"], "--min-psnr", "30")
        commands = doc["provenance"]["commands"]
        modern = supports_option(FFMPEG, "-fps_mode")
        self.assertEqual(len(commands), 3 if modern else 6)
        # Older builds record each rejected modern spelling and its successful legacy retry.
        if not modern:
            for attempted, retried in zip(commands[::2], commands[1::2]):
                i = attempted.index("-fps_mode")
                expected = attempted[:i] + ["-vsync", "0"] + attempted[i + 2:]
                self.assertEqual(retried, expected)
        for cmd in commands:
            sync = ["-fps_mode", "passthrough"] if "-fps_mode" in cmd else ["-vsync", "0"]
            self.assertEqual(cmd[cmd.index(sync[0]):cmd.index(sync[0]) + 2], sync)
            inspected = list(cmd)
            if sync[0] == "-vsync":
                i = inspected.index("-vsync")
                del inspected[i:i + 2]
            self.assertEqual(self.seek_flags(inspected), [], cmd)
            self.assertTrue(all(isinstance(part, str) for part in cmd))
            self.assertIn("-nostdin", cmd)
            self.assertIn("-hide_banner", cmd)
            if modern:
                self.assertEqual(sync, ["-fps_mode", "passthrough"])
        self.assertEqual([c[c.index("-f") + 1] for c in commands if "framemd5" in c], ["framemd5", "framemd5"] if modern else ["framemd5"] * 4)
        # negative control: the detector does flag seeking or truncating options
        self.assertEqual(self.seek_flags(["ffmpeg", "-ss", "3", "-i", "x", "-frames:v", "10"]), ["-ss", "-frames:v"])

    @staticmethod
    def seek_flags(cmd):
        return [part for part in cmd if part in ("-ss", "-sseof", "-seek_timestamp", "-t", "-to", "-vframes",
                                                  "-frames:v", "-r", "-vsync")]

    def test_commands_are_argument_lists_only(self):
        with self.assertRaises(TypeError):
            common.run("ffmpeg -version")          # a shell string is refused by the shared runner
        common.run([FFMPEG, "-hide_banner", "-version"])    # a list is accepted


# ---------------------------------------------------------------------------
# Hard rules for the file this builder owns
# ---------------------------------------------------------------------------

FORBIDDEN_IMPORTS = {"socket", "urllib", "http", "requests", "ftplib", "smtplib", "pickle", "marshal", "ctypes",
                     "base64", "subprocess"}
FORBIDDEN_NAMES = {"eval", "exec", "compile", "__import__", "getenv", "environ", "system", "popen"}


def rule_violations(source):
    found = []
    for node in ast.walk(ast.parse(source)):
        if isinstance(node, ast.Import):
            found += [a.name.split(".")[0] for a in node.names if a.name.split(".")[0] in FORBIDDEN_IMPORTS]
        elif isinstance(node, ast.ImportFrom) and node.module and node.module.split(".")[0] in FORBIDDEN_IMPORTS:
            found.append(node.module)
        elif isinstance(node, ast.Name) and node.id in FORBIDDEN_NAMES:
            found.append(node.id)
        elif isinstance(node, ast.Attribute) and node.attr in FORBIDDEN_NAMES:
            found.append(node.attr)
        elif isinstance(node, ast.keyword) and node.arg == "shell":
            found.append("shell=")
    return found


class HardRules(unittest.TestCase):
    def test_scanner_catches_violations_and_passes_clean_code(self):
        bad = "import re\nre.compile('x')\nimport urllib.request\nos.getenv('A')\nf(shell=True)\n"
        self.assertEqual(sorted(set(rule_violations(bad))), sorted(["compile", "urllib", "getenv", "shell="]))
        self.assertEqual(rule_violations("import re\nre.match('a', 'b')\n"), [])

    def test_qa_compare_obeys_the_hard_rules(self):
        with open(CMP_SCRIPT, "rb") as fh:
            raw = fh.read()
        self.assertEqual(rule_violations(raw.decode("utf-8")), [])
        self.assertNotIn(b"\r", raw, "LF line endings only")
        text = raw.decode("ascii")      # ASCII-only source
        lines = text.split("\n")
        self.assertEqual(lines[0], "#!/usr/bin/env python3")
        header = "\n".join(line for line in lines[1:25] if line.startswith("#"))
        for word in ("Purpose", "Inputs", "Outputs", "Exit codes"):
            self.assertIn(word, header)

    def test_qa_compare_only_opens_files_for_reading_or_not_at_all(self):
        with open(CMP_SCRIPT, "rb") as fh:
            tree = ast.parse(fh.read().decode("utf-8"))
        for node in ast.walk(tree):
            if isinstance(node, ast.Call) and getattr(node.func, "id", "") == "open":
                self.fail("qa_compare.py should not open files itself (writes nothing, hashes via common)")

    def test_no_bytecode_left_in_the_package(self):
        self.assertFalse(os.path.isdir(os.path.join(SCRIPTS, "__pycache__")))


if __name__ == "__main__":
    unittest.main()
